// =====================================================
// BRIEFING DIÁRIO — Lótus Business
// =====================================================

const hoje = new Date();
const diasSemana = ['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado'];
const meses = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
const diaNome = diasSemana[hoje.getDay()];
const diaNum = hoje.getDate();
const mesNome = meses[hoje.getMonth()];

// Coletar dados dos nós anteriores (com fallback seguro)
let leadsData = []; try { leadsData = $('HubSpot - Leads sem contato +3d').all() || []; } catch(e) {}
let dealsData = []; try { dealsData = $('HubSpot - Ofertas Ativas').all() || []; } catch(e) {}
let reunioesData = []; try { reunioesData = $('Google Agenda - Reuniões de Hoje').all() || []; } catch(e) {}

// Helper: extrai string de campo HubSpot (suporta string direta ou objeto {value:...})
const getStr = (val) => {
  if (!val) return '';
  if (typeof val === 'string') return val;
  if (typeof val === 'object' && val.value !== undefined) return String(val.value);
  return '';
};

// ---- REUNIÕES ----
let reunioesLinhas = '';
if (reunioesData.length === 0) {
  reunioesLinhas = '  Nenhuma reunião agendada';
} else {
  reunioesLinhas = reunioesData.map(r => {
    const ev = r.json;
    const inicio = ev.start?.dateTime
      ? new Date(ev.start.dateTime).toLocaleTimeString('pt-BR', {hour:'2-digit', minute:'2-digit'})
      : 'dia todo';
    const titulo = ev.summary || 'Sem título';
    const local = ev.location ? ` | ${ev.location}` : '';
    return `  ${inicio} — ${titulo}${local}`;
  }).join('\n');
}

// ---- LEADS SEM CONTATO ----
let leadsLinhas = '';
if (leadsData.length === 0) {
  leadsLinhas = '  Todos os leads contactados';
} else {
  const top10 = leadsData.slice(0, 10);
  leadsLinhas = top10.map(l => {
    const props = l.json.properties || l.json || {};
    const nome = [
      getStr(props.firstname),
      getStr(props.lastname)
    ].filter(Boolean).join(' ') || getStr(props.email) || 'Sem nome';
    const status = getStr(props.hs_lead_status) || 'N/D';
    const ultimoContato = getStr(props.notes_last_updated)
      ? new Date(getStr(props.notes_last_updated)).toLocaleDateString('pt-BR')
      : 'nunca';
    return `  • ${nome} | ${status} | último: ${ultimoContato}`;
  }).join('\n');
  if (leadsData.length > 10) {
    leadsLinhas += `\n  ... e mais ${leadsData.length - 10} leads`;
  }
}

// ---- OFERTAS ATIVAS ----
let dealsLinhas = '';
let totalPipeline = 0;
if (dealsData.length === 0) {
  dealsLinhas = '  Nenhuma oferta ativa no pipeline';
} else {
  const top10 = dealsData.slice(0, 10);
  dealsLinhas = top10.map(d => {
    const props = d.json.properties || d.json || {};
    const nome = getStr(props.dealname) || 'Sem nome';
    const valorRaw = Number(getStr(props.amount)) || 0;
    const valor = valorRaw > 0 ? `R$ ${valorRaw.toLocaleString('pt-BR')}` : 'Sem valor';
    const stage = getStr(props.dealstage) || 'N/D';
    totalPipeline += valorRaw;
    return `  • ${nome} | ${valor} | ${stage}`;
  }).join('\n');
  if (dealsData.length > 10) {
    dealsLinhas += `\n  ... e mais ${dealsData.length - 10} ofertas`;
  }
}

const totalFormatado = totalPipeline > 0
  ? `R$ ${totalPipeline.toLocaleString('pt-BR')}`
  : 'N/D';

// ---- MONTAR MENSAGEM ----
const mensagem = [
  `📋 *BRIEFING ${diaNome.toUpperCase()}, ${diaNum} de ${mesNome}*`,
  '',
  `📅 *REUNIÕES HOJE (${reunioesData.length})*`,
  reunioesLinhas,
  '',
  `🔴 *LEADS SEM CONTATO +3 DIAS (${leadsData.length})*`,
  leadsLinhas,
  '',
  `💼 *OFERTAS ATIVAS (${dealsData.length}) | Pipeline: ${totalFormatado}*`,
  dealsLinhas,
  '',
  `_Gerado automaticamente às 7h30 — Lótus Business_`
].join('\n');

return [{ json: { mensagem, totalLeadsSemContato: leadsData.length, totalDeals: dealsData.length, totalReunioes: reunioesData.length } }];
